CREATE OR REPLACE FUNCTION public.landlord_unit_ids() RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT u.id FROM units u WHERE has_role(auth.uid(),'landlord') AND (EXISTS(SELECT 1 FROM properties p WHERE p.id=u.property_id AND p.landlord_id=auth.uid() AND coalesce(p.owner_type,'landlord')='landlord') OR EXISTS(SELECT 1 FROM unit_assignments a WHERE a.unit_id=u.id AND a.user_id=auth.uid() AND a.role='landlord' AND a.start_date<=current_date AND (a.end_date IS NULL OR a.end_date>=current_date)) OR EXISTS(SELECT 1 FROM meters m WHERE m.landlord_id=auth.uid() AND (m.unit_id=u.id OR (m.unit_id IS NULL AND m.meter_number IN(u.electricity_meter_no,u.water_meter_no,u.gas_meter_no))))) $$;
CREATE OR REPLACE FUNCTION public.landlord_meter_ids() RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.id FROM meters m WHERE has_role(auth.uid(),'landlord') AND (m.landlord_id=auth.uid() OR EXISTS(SELECT 1 FROM units u WHERE u.id IN(SELECT public.landlord_unit_ids()) AND (m.unit_id=u.id OR (m.unit_id IS NULL AND m.meter_number IN(u.electricity_meter_no,u.water_meter_no,u.gas_meter_no))))) $$;
CREATE OR REPLACE FUNCTION public.landlord_property_ids() RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id FROM properties p WHERE has_role(auth.uid(),'landlord') AND ((p.landlord_id=auth.uid() AND coalesce(p.owner_type,'landlord')='landlord') OR EXISTS(SELECT 1 FROM units u WHERE u.property_id=p.id AND u.id IN(SELECT public.landlord_unit_ids()))) $$;
REVOKE ALL ON FUNCTION public.landlord_unit_ids(),public.landlord_meter_ids(),public.landlord_property_ids() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.landlord_unit_ids(),public.landlord_meter_ids(),public.landlord_property_ids() TO authenticated;
CREATE POLICY landlord_linked_properties ON public.properties FOR SELECT TO authenticated USING(id IN(SELECT public.landlord_property_ids()));
CREATE POLICY landlord_linked_units ON public.units FOR SELECT TO authenticated USING(id IN(SELECT public.landlord_unit_ids()));
CREATE POLICY landlord_linked_meters ON public.meters FOR SELECT TO authenticated USING(id IN(SELECT public.landlord_meter_ids()));
CREATE POLICY landlord_linked_tokens ON public.meter_tokens FOR SELECT TO authenticated USING(meter_id IN(SELECT public.landlord_meter_ids()));
CREATE POLICY landlord_linked_bank_payments ON public.bank_notifications FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM meters m WHERE m.id IN(SELECT public.landlord_meter_ids()) AND m.meter_number=bank_notifications.meter_number));
CREATE OR REPLACE FUNCTION public.landlord_managing_vendors() RETURNS TABLE(id text,name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT DISTINCT m.vendor_id,u.name FROM meters m JOIN users u ON u.id::text=m.vendor_id WHERE m.id IN(SELECT public.landlord_meter_ids()) AND has_role(u.id,'vendor') UNION SELECT DISTINCT p.created_by::text,u.name FROM properties p JOIN users u ON u.id=p.created_by WHERE p.id IN(SELECT public.landlord_property_ids()) AND has_role(u.id,'vendor') $$;
REVOKE ALL ON FUNCTION public.landlord_managing_vendors() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.landlord_managing_vendors() TO authenticated;